1	// Shared per-spec data setup (DESIGN.md §9, BASE_CHECKLIST.md §D). Each spec's beforeEach RESETS
2	// then SEEDS via the app's /__test__ endpoint — this is Arrange, not Assert. Specs still ASSERT
3	// only through the UI (data-testid).
4	//
5	// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
6	// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
7	// silent failure would surface later as confusing, misattributed assertion failures on unrelated
8	// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
9	// the break is attributed to the seed contract, and so an implementer running its own spec sees the
10	// broken endpoint immediately instead of shipping it. This helper is fixed test infrastructure — the
11	// evolving surface is the server-side /__test__ endpoint, not this client.
12	import { request, type APIResponse } from '@playwright/test';
13	
14	const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;
15	
16	async function must(res: Promise<APIResponse>, what: string): Promise<void> {
17	  const r = await res;
18	  if (!r.ok()) {
19	    const body = (await r.text().catch(() => '')).slice(0, 500);
20	    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
21	  }
22	}
23	
24	export async function resetAndSeed(fixture: unknown): Promise<void> {
25	  const api = await request.newContext({ baseURL: BASE });
26	  try {
