1	// Acceptance test for the change request:
2	//   "Let me put labels on projects so I can group them."
3	//
4	// A project carries LABELS (tags). On a project's detail page (/projects/<id>) they live in their
5	// own region (project-tags) holding the list of the project's labels (project-tags-list): each label
6	// is its own chip (project-tag-<id>, keyed by the tag's id) carrying the label's text, with a control
7	// to take that label off the project (project-tag-remove-<id>). The region offers a control to put a
8	// new label on the project (project-tag-add) submitted with project-tag-add-submit.
9	//
10	// Labels GROUP projects: the same label can sit on more than one project. A project's label list
11	// belongs to THAT project — a label on a different project is not shown here.
12	//
13	// Putting a label on a project and taking one off are audited so the grouping can be checked back
14	// later: each records exactly one line — `PROJECT_TAGGED project=<project> tag=<tag>` when a label is
15	// added, `PROJECT_UNTAGGED project=<project> tag=<tag>` when one is removed. The <project> / <tag>
16	// fields identify the project and the tag; the test binds to the MEANING by accepting either the
17	// seeded id or the seeded name for each, rather than pinning one choice of identifier. Merely viewing
18	// a project's labels records nothing.
19	//
20	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
21	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients` honours
22	// { id, name, email }, `projects` honours { id, name, clientId }, `tags` honours { id, name } and
23	// `projectTags` (the join putting a label on a project) honours { projectId, tagId }.
24	import { test, expect, type Page, type Locator } from '@playwright/test';
25	import { resetAndSeed } from '../support/seed';
26	import { auditLines } from '../support/audit';
27	
28	// A label chip is project-tag-<id>. The prefix "project-tag-" is ALSO shared by the add control
29	// (project-tag-add / -add-submit) and the per-chip remove control (project-tag-remove-<id>), so the
30	// chips are the elements under that prefix that are neither add nor remove.
31	const tagChips = (page: Page): Locator =>
32	  page.locator(
33	    '[data-testid^="project-tag-"]:not([data-testid^="project-tag-add"]):not([data-testid^="project-tag-remove"])',
34	  );
35	
36	// Locate the one chip carrying a given label text, regardless of its server-assigned id. Label texts
37	// in each test are chosen distinct — none a substring of another — so this is unambiguous.
38	const chipByLabel = (page: Page, label: string): Locator =>
39	  tagChips(page).filter({ hasText: label });
40	
41	// The remove control for a chip. Its concrete id (project-tag-remove-<id>) is the tag's id, which for
42	// a freshly added label is assigned by the server, so find it WITHIN the chip rather than by id.
43	const removeIn = (chip: Locator): Locator => chip.locator('[data-testid^="project-tag-remove-"]');
44	
45	// Audit matchers. The <project> / <tag> fields may be written as the id or the name, so accept either
46	// (a known tag id is passed where the tag was seeded; otherwise any id is allowed alongside the name).
47	const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
48	type Ref = { id: number; name: string };
49	const taggedRe = (p: Ref, t: { id?: number; name: string }) =>
50	  new RegExp(`^PROJECT_TAGGED project=(?:${p.id}|${esc(p.name)}) tag=(?:${t.id ?? '\\d+'}|${esc(t.name)})$`);
51	const untaggedRe = (p: Ref, t: { id?: number; name: string }) =>
52	  new RegExp(`^PROJECT_UNTAGGED project=(?:${p.id}|${esc(p.name)}) tag=(?:${t.id ?? '\\d+'}|${esc(t.name)})$`);
53	
54	const linesMatching = (re: RegExp): string[] => auditLines().filter((l) => re.test(l));
55	
56	async function gotoProject(page: Page, id: number): Promise<void> {
57	  await page.goto(`/projects/${id}`);
58	  await expect(page.getByTestId('project-detail-page')).toBeVisible();
59	  await expect(page.getByTestId('project-tags')).toBeVisible();
60	}
61	
62	test.describe("A project's labels", () => {
63	  test('a project shows its own labels, and not labels that belong to another project', async ({
64	    page,
65	  }) => {
66	    await resetAndSeed({
67	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
68	      projects: [
69	        { id: 1, name: 'Website Redesign', clientId: 1 },
70	        { id: 2, name: 'Mobile App', clientId: 1 },
71	      ],
72	      tags: [
73	        { id: 1, name: 'urgent' },
74	        { id: 2, name: 'backend' },
75	        { id: 3, name: 'design' },
76	      ],
77	      projectTags: [
78	        { projectId: 1, tagId: 1 },
79	        { projectId: 1, tagId: 2 },
80	        // A label on a DIFFERENT project — it must not appear on project 1's list.
81	        { projectId: 2, tagId: 3 },
82	      ],
83	    });
84	
85	    await gotoProject(page, 1);
86	    await expect(page.getByTestId('project-tags-list')).toBeVisible();
87	
88	    // Only this project's two labels are shown, each keyed by its tag id and carrying its text.
89	    await expect(tagChips(page)).toHaveCount(2);
90	    await expect(page.getByTestId('project-tag-1')).toContainText('urgent');
91	    await expect(page.getByTestId('project-tag-2')).toContainText('backend');
92	
93	    // The other project's label is nowhere on this page.
94	    await expect(page.getByTestId('project-tag-3')).toHaveCount(0);
95	    await expect(page.getByTestId('project-tags')).not.toContainText('design');
96	
97	    // Merely viewing a project's labels records nothing — a record is kept on tag/untag, not on view.
98	    expect(auditLines()).toEqual([]);
99	  });
100	
101	  test('a project with no labels shows an empty label list', async ({ page }) => {
102	    await resetAndSeed({
103	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
104	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
105	      tags: [{ id: 1, name: 'urgent' }],
106	      // The tag exists but is not put on this project.
107	      projectTags: [],
108	    });
109	
110	    await gotoProject(page, 1);
111	
112	    // The region is present but holds no labels.
113	    await expect(tagChips(page)).toHaveCount(0);
114	    await expect(page.getByTestId('project-tags')).not.toContainText('urgent');
115	    expect(auditLines()).toEqual([]);
116	  });
117	
118	  test('putting a label on a project shows it, persists, and records it once', async ({ page }) => {
119	    await resetAndSeed({
120	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
121	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
122	      tags: [],
123	      projectTags: [],
124	    });
125	
126	    const project = { id: 1, name: 'Website Redesign' };
127	
128	    await gotoProject(page, 1);
129	    await expect(tagChips(page)).toHaveCount(0);
130	
131	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
132	    // tagging (not the seeding) wrote it.
133	    expect(auditLines()).toEqual([]);
134	
135	    // Put a label on the project.
136	    await expect(page.getByTestId('project-tag-add')).toBeVisible();
137	    await page.getByTestId('project-tag-add').fill('urgent');
138	    await page.getByTestId('project-tag-add-submit').click();
139	
140	    // The label joins the list as its own chip, carrying its text and offering a control to take it
141	    // off again. Its id is server-assigned, so locate it by the text it carries.
142	    const chip = chipByLabel(page, 'urgent');
143	    await expect(chip).toHaveCount(1);
144	    await expect(chip).toContainText('urgent');
145	    await expect(removeIn(chip)).toBeVisible();
146	    await expect(tagChips(page)).toHaveCount(1);
147	
148	    // Exactly one record was kept for this tagging, identifying the project and the label.
149	    expect(linesMatching(taggedRe(project, { name: 'urgent' }))).toHaveLength(1);
150	    expect(auditLines()).toHaveLength(1);
151	
152	    // The label is held by the server, not just the page: it survives a fresh load, and reloading does
153	    // not record the tagging a second time.
154	    await page.reload();
155	    await expect(page.getByTestId('project-tags')).toBeVisible();
156	    await expect(chipByLabel(page, 'urgent')).toHaveCount(1);
157	    await expect(tagChips(page)).toHaveCount(1);
158	    expect(linesMatching(taggedRe(project, { name: 'urgent' }))).toHaveLength(1);
159	    expect(auditLines()).toHaveLength(1);
160	  });
161	
162	  test('taking a label off a project drops it, leaves the others, persists, and records it once', async ({
163	    page,
164	  }) => {
165	    await resetAndSeed({
166	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
167	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
168	      tags: [
169	        { id: 1, name: 'urgent' },
170	        { id: 2, name: 'backend' },
171	      ],
172	      projectTags: [
173	        { projectId: 1, tagId: 1 },
174	        { projectId: 1, tagId: 2 },
175	      ],
176	    });
177	
178	    const project = { id: 1, name: 'Website Redesign' };
179	
180	    await gotoProject(page, 1);
181	    await expect(tagChips(page)).toHaveCount(2);
182	    await expect(page.getByTestId('project-tag-1')).toContainText('urgent');
183	    await expect(page.getByTestId('project-tag-2')).toContainText('backend');
184	    expect(auditLines()).toEqual([]);
185	
186	    // Take the "urgent" label off the project.
187	    await page.getByTestId('project-tag-remove-1').click();
188	
189	    // Only that label is gone; the other remains on the project.
190	    await expect(page.getByTestId('project-tag-1')).toHaveCount(0);
191	    await expect(tagChips(page)).toHaveCount(1);
192	    await expect(page.getByTestId('project-tag-2')).toContainText('backend');
193	    await expect(page.getByTestId('project-tags')).not.toContainText('urgent');
194	
195	    // Exactly one record was kept for this untagging, identifying the project and the label.
196	    expect(linesMatching(untaggedRe(project, { id: 1, name: 'urgent' }))).toHaveLength(1);
197	    expect(auditLines()).toHaveLength(1);
198	
199	    // The removal is held by the server: it survives a fresh load without recording anything more.
200	    await page.reload();
201	    await expect(page.getByTestId('project-tags')).toBeVisible();
202	    await expect(page.getByTestId('project-tag-1')).toHaveCount(0);
203	    await expect(page.getByTestId('project-tag-2')).toContainText('backend');
204	    await expect(tagChips(page)).toHaveCount(1);
205	    expect(linesMatching(untaggedRe(project, { id: 1, name: 'urgent' }))).toHaveLength(1);
206	    expect(auditLines()).toHaveLength(1);
207	  });
208	
209	  test('the same label groups more than one project', async ({ page }) => {
210	    // "urgent" sits on two different projects — that shared label is how they are grouped.
211	    await resetAndSeed({
212	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
213	      projects: [
214	        { id: 1, name: 'Website Redesign', clientId: 1 },
215	        { id: 2, name: 'Mobile App', clientId: 1 },
216	      ],
217	      tags: [
218	        { id: 1, name: 'urgent' },
219	        { id: 2, name: 'backend' },
220	      ],
221	      projectTags: [
222	        { projectId: 1, tagId: 1 },
223	        // The same "urgent" label also on project 2, plus a label unique to project 2.
224	        { projectId: 2, tagId: 1 },
225	        { projectId: 2, tagId: 2 },
226	      ],
227	    });
228	
229	    // Project 1 carries the shared label.
230	    await gotoProject(page, 1);
231	    await expect(tagChips(page)).toHaveCount(1);
232	    await expect(page.getByTestId('project-tag-1')).toContainText('urgent');
233	
234	    // Project 2 carries the SAME label (same tag id) alongside its own.
235	    await gotoProject(page, 2);
236	    await expect(tagChips(page)).toHaveCount(2);
237	    await expect(page.getByTestId('project-tag-1')).toContainText('urgent');
238	    await expect(page.getByTestId('project-tag-2')).toContainText('backend');
239	
240	    // Reading the grouping records nothing.
241	    expect(auditLines()).toEqual([]);
242	  });
243	});
