    expect(auditLines()).toHaveLength(1);
  });

  test('picking a different contact replaces the main contact — only one at a time', async ({
    page,
  }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
